#include <bits/stdc++.h>using namespace std;#define int long longconst int N = 1e5 + 10;int n,k,ans;vector<int> a,G[N]; void dfs(int u,int fa,int cnt){    if(cnt > k)return ;    bool isLeaf = 1;    for(auto &v : G[u]){        if(v == fa)continue;        isLeaf = 0;        int ncnt = cnt;        if(a[v] == 1)ncnt = cnt + 1;        else ncnt = 0;        dfs(v,u,ncnt);    }    if(isLeaf)ans++;} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> n >> k;    a.resize(n + 1);    for(int i=1;i<=n;i++){        cin >> a[i];    }    for(int i=1;i<=n-1;i++){        int u,v;cin >> u >> v;        G[u].emplace_back(v);        G[v].emplace_back(u);    }    if(n == 1){        if(k == 0){            cout << 0 << '\n';        }else{            cout << 1 << '\n';        }        return 0;    }    dfs(1,0,a[1]);    cout << ans << '\n';    return 0;}